INSERT INTO campaigns (title,description,host_organizer,campaign_url,image_url,start_date,end_date,region,category,status,submission_type) VALUES ('탄탄대로 챌린지','제로서울과 함께하는 탄소제로 도전기. 매달 주어지는 탄소중립 미션을 수행, 인증샷 등록 등 실천형 환경 보호 캠페인','서울시 (제로서울)','https://event.seoul.go.kr/zeroseoul/','https://news.seoul.go.kr/env/climate-environment/climate-change-strategy/zero-seoul','2025-06-05','2025-11-30','서울특별시','ENERGY','ACTIVE','MANUAL_GUIDE'),('11월의 해녀와 바다','거제·영도 해녀와 함께하는 해양 플로깅(수중·해안 정화) 캠페인. 해양 쓰레기 수거를 통해 바다 정화와 해양 환경 보호를 실천하는 시민참여형 활동. 11월 1일 거제 가조도, 11월 22일 영도구 중리에서 열림. 다이버/라이프가드/일반 시민 모두 참여 가능. 인스타 DM 또는 밴드 투표로 참가 신청','해녀와 바다(haenyeo_and_thesea)','https://www.instagram.com/p/DQMYGQmAWA-/','https://www.instagram.com/p/DQMYGQmAWA-/','2025-11-01','2025-11-22','경남 거제시 가조도, 부산 영도구 중리','CONSERVATION','EXPECT','MANUAL_GUIDE'),('반려해변 프로그램','해변을 입양해 직접 관리·정화하며 해양쓰레기 저감과 해안 보전을 실천하는 시민참여형 장기 캠페인. 모든 단체·기업·학교가 참여 가능하며, 정기적 해변 정화·쓰레기 데이터 기록·캠페인 운영 등으로 정책 자료로 활용','해양환경공단','https://www.meis.go.kr/mli/rjct/info.do','https://www.meis.go.kr/mli/rjct/info.do','2025-10-18','2025-10-18','서울특별시','CONSERVATION','EXPECT','MANUAL_GUIDE'),('2025 제주남방큰돌고래와 함께하는 플로깅','제주 바다와 제주남방큰돌고래를 지키는 플로깅 캠페인. 참가자들이 가족, 친구, 연인과 함께 해변을 걷고 쓰레기를 줍는 집단 실천형 환경 보호 활동. 깨끗한 바다와 돌고래 보호를 목표로 함','플로깅 with 제주돌고래 (인스타그램: @plogging_with.jeju.dolphin), 안녕놀이터 등 협력','https://helloplay.kr/program/?bmode=view&idx=168149833&utm_source=chatgpt.com','https://helloplay.kr/program/?bmode=view&idx=168149833&utm_source=chatgpt.com','2025-10-25','2025-11-15','제주특별자치도','CONSERVATION','EXPECT','MANUAL_GUIDE'),('2025 깨끗한 원주 만들기 비대면 환경정화 봉사활동','원주 내 공공장소(천, 공원, 둘레길 등)에서 2시간 이내 환경정화 자원봉사 활동을 진행. 자율참여로 활동사진, 봉사일지를 제출하여 실적이 인증됨. 1365자원봉사포털 사전신청 필수.','강원특별자치도 원주시, 원주시자원봉사센터','https://www.1365.go.kr/vols/P9210/partcptn/timeCptn.do?progrmRegistNo=3334809&type=show','https://www.1365.go.kr/vols/P9210/partcptn/timeCptn.do?progrmRegistNo=3334809&type=show','2025-09-01','2025-11-30','강원특별자치도 원주시','CONSERVATION','EXPECT','MANUAL_GUIDE'),('시민공원 환경정화','부산시민공원 내 자원봉사캠프 주관 환경정화활동. 매일 오전, 오후 팀으로 나뉘어 시민들이 함께 공원 내 쓰레기 수거·쾌적한 환경조성에 동참하는 집단 환경 캠페인','부산시민공원 자원봉사캠프','https://www.busan1365.kr/program/?&q=list&page=&sfl=&stx=&s_view=&gubun=&q=view&uid=4','https://www.busan1365.kr/program/?&q=list&page=&sfl=&stx=&s_view=&gubun=&q=view&uid=4','2025-10-01','2025-10-31','부산광역시 부산진구 시민공원로 73(연지동), 부산시민공원','CONSERVATION','ACTIVE','MANUAL_GUIDE'),('익산 청소년문화의거리 플로깅 및 폐화분 리사이클링 활동','익산 청소년들이 문화의거리 일대를 조깅하며 쓰레기 줍기(플로깅), 폐화분 리사이클링까지 실천하는 환경·생태계 보호 오프라인 자원봉사','익산청소년자치공간 다꿈, 전북특별자치도 익산시','https://www.1365.go.kr/vols/P9210/partcptn/timeCptn.do?progrmRegistNo=3330826&type=show','https://www.1365.go.kr/vols/P9210/partcptn/timeCptn.do?progrmRegistNo=3330826&type=show','2025-10-31','2025-10-31','전북특별자치도 익산시 무왕로11길 6-29','RECYCLING','EXPECT','MANUAL_GUIDE'),('홍대 레드로드 골목여행, 플로깅 및 분리수거 봉사','마포구 서교동·홍대 일대 골목을 해설사와 함께 걷고, 조별로 쓰레기를 줍는 플로깅 및 탐방 후 재활용 분리수거 활동이 결합된 오프라인 환경 체험 봉사. 누구나 참여 가능, 단체 접수별 담당자 문의 필수','서교동주민센터, 행정안전부','https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3328009','https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3328009','2025-10-31','2025-11-07','서울특별시 마포구 서교동 및 홍대입구역-레드로드발전소-김대중도서관-산울림소극장-홍익대-상상마당-서교동주민센터','RECYCLING','ACTIVE','MANUAL_GUIDE'),('김포시하천살리기추진단 하천정화 및 곤충뱃지 만들기 캠페인','하천정화(쓰레기줍기), 나무편 곤충 뱃지 만들기, 하천 생태·기후 변화 교육까지 결합된 오프라인 참가형 환경생태 프로그램. 학생/성인/가족 모두 참여 가능하며, 전문 강사 인솔로 진행됨','김포시하천살리기추진단, 김포시','https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3359663','https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3359663','2025-11-08','2025-11-08','경기도 김포시 한강신도시 호수공원, 마산동 일대(김포한강4로 419-14)','RECYCLING','EXPECT','MANUAL_GUIDE'),('강남구 플로깅로드 오프라인 환경정화 봉사','강남구자원봉사센터 주관, 이타서울 웹서비스와 연계된 오프라인 플로깅(쓰레기 줍기) 집단 환경정화 캠페인. 양재역 인근을 걸으며 직접 쓰레기를 수거, 기록하고, 탄소중립 실천을 독려함','강남구자원봉사센터','[**https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3359138**](https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3359138)','[**https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3359138**](https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3359138)','2025-11-14','2025-11-14','서울특별시 강남구 도곡1동주민센터, 양재역 주변','ENERGY','ACTIVE','MANUAL_GUIDE');